require_once __DIR__.'/../config/app.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);$product=$s->fetch();if(!$product){http_response_code(404);exit('Produk tidak ditemukan.');}$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();$errors=[];if(is_post()){verify_csrf();$name=trim($_POST['name']??'');$sku=strtoupper(trim($_POST['sku']??''));$category=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$min=max(0,(int)($_POST['minimum_stock']??0));$check=db()->prepare('SELECT id FROM products WHERE sku=? AND id<>?');$check->execute([$sku,$id]);if($name===''||$category<1||$price<0)$errors[]='Data produk tidak valid.';if($check->fetch())$errors[]='SKU sudah digunakan.';if(!$errors){$image=$product['image'];$newImage=null;try{if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$newImage=upload_image($_FILES['image'],'uploads/products','product');$image=$newImage;}db()->prepare('UPDATE products SET category_id=?,sku=?,name=?,slug=?,description=?,price=?,minimum_stock=?,image=?,is_featured=?,is_active=? WHERE id=?')->execute([$category,$sku,$name,unique_slug('products',$name,$id),trim($_POST['description']??''),$price,$min,$image,isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0,$id]);if($newImage)remove_upload($product['image']);flash('success','Produk berhasil diperbarui.');redirect('admin/products.php');}catch(Throwable $e){remove_upload($newImage);$errors[]=$e->getMessage();}}}$pageTitle='Edit Produk';require APP_ROOT.'/includes/admin-header.php';?>
<?php foreach($errors as $error):?><div class="alert alert-danger"><?= e($error) ?></div><?php endforeach;require __DIR__.'/product-form.php';require APP_ROOT.'/includes/admin-footer.php';?>
